async function authenticatedAgent(machineId:string,method:string,routePath:string,headers:Record<string,unknown>){
 const machine=await db.machine.findUnique({where:{id:machineId},select:{agentPublicKey:true,agentVersion:true,moderationStatus:true,keyRevokedAt:true}});
 if(!machine||machine.keyRevokedAt||machine.moderationStatus!==ModerationStatus.CLEAR)return null;
 const valid=await verifyAgentRequest(redis,machineId,machine.agentPublicKey,method,routePath,headers['x-agent-timestamp'] as string|string[]|undefined,headers['x-agent-signature'] as string|string[]|undefined);
 return valid?machine:null;
}
// Same as authenticatedAgent, plus binding to the exact body bytes (verifyAgentRequestV2):
// V1 alone only covers method|path|machineId|timestamp, so anyone able to alter an agent
// request body in flight (e.g. a compromised proxy) could rewrite job outcomes/log entries
// without invalidating the signature. Required for every agent endpoint that carries a body.
async function authenticatedAgentWithBody(machineId:string,method:string,routePath:string,headers:Record<string,unknown>,rawBody:Buffer|undefined){
 const machine=await authenticatedAgent(machineId,method,routePath,headers);
 if(!machine)return null;
 if(!rawBody)return null;
 const validV2=await verifyAgentRequestV2(redis,machineId,machine.agentPublicKey,method,routePath,rawBody,{timestamp:headers['x-agent-timestamp'] as string|string[]|undefined,nonce:headers['x-agent-nonce'] as string|string[]|undefined,bodySha256:headers['x-agent-body-sha256'] as string|string[]|undefined,signature:headers['x-agent-signature-v2'] as string|string[]|undefined,version:headers['x-agent-signature-version'] as string|string[]|undefined});
 return validV2?machine:null;
}
