app.post('/jobs/:id/cancel',async(req,reply)=>{const session=await requireSession(req,reply,redis);if(!session)return;const {id}=z.object({id:z.string().cuid()}).parse(req.params);const job=await db.job.findFirst({where:{id,renterId:session.userId},select:{status:true}});if(!job)return reply.code(404).send({error:'job_not_found'});const target=job.status===JobStatus.QUEUED?JobStatus.CANCELLED:JobStatus.CANCEL_REQUESTED;if(!canTransitionJob(job.status,target))return reply.code(409).send({error:'job_not_cancellable',status:job.status});return db.job.update({where:{id},data:{status:target,cancelRequestedAt:new Date(),...(target===JobStatus.CANCELLED?{finishedAt:new Date()}:{})},select:{id:true,status:true}});});
const jobLeaseFields={attemptId:z.string().cuid().optional(),leaseToken:z.string().regex(JOB_LEASE_TOKEN_RE).optional()};
type JobLeaseBody={attemptId?:string|undefined;leaseToken?:string|undefined};
function jobLeaseCredentialsFromBody(body:JobLeaseBody):JobLeaseCredentials|null{return body.attemptId&&body.leaseToken?{attemptId:body.attemptId,leaseToken:body.leaseToken}:null;}
function completeLeasePair(body:JobLeaseBody):boolean{return (body.attemptId===undefined)===(body.leaseToken===undefined);}
function executionWhere(jobId:string,machineId:string,body:JobLeaseBody,now:Date):Prisma.JobWhereInput{const credentials=jobLeaseCredentialsFromBody(body);return credentials?jobLeaseWhere({jobId,machineId,credentials,now}):{id:jobId,machineId,currentAttemptId:null,leaseTokenHash:null,leaseExpiresAt:null};}
function executionRefresh(body:JobLeaseBody,now:Date){return {lastAgentReportAt:now,updatedAt:now,...(jobLeaseCredentialsFromBody(body)?{leaseExpiresAt:jobLeaseExpiresAt(now,config.JOB_RECLAIM_AFTER_SECONDS)}:{})};}
function terminalExecutionMatches(job:{currentAttemptId:string|null;leaseTokenHash:string|null},body:JobLeaseBody):boolean{const credentials=jobLeaseCredentialsFromBody(body);return credentials?terminalAttemptMatches({...job,credentials}):job.currentAttemptId===null&&job.leaseTokenHash===null;}
const terminalJobStatusSet=new Set<JobStatus>([JobStatus.COMPLETED,JobStatus.FAILED,JobStatus.CANCELLED,JobStatus.TIMED_OUT,JobStatus.REJECTED,JobStatus.QUARANTINED]);

app.get('/agent/jobs/next/:machineId',{config:{rateLimit:{max:60,timeWindow:'1 minute'}}},async(req,reply)=>{const {machineId}=z.object({machineId:z.string().cuid()}).parse(req.params);const routePath=`/agent/jobs/next/${machineId}`;const machine=await authenticatedAgent(machineId,'GET',routePath,req.headers);if(!machine)return reply.code(401).send({error:'invalid_agent_request'});if(!supportsJobLeaseProtocol(machine.agentVersion)){req.log.warn({machineId,agentVersion:machine.agentVersion,requiredVersion:JOB_LEASE_PROTOCOL_VERSION},'agent_job_protocol_upgrade_required');return reply.code(426).send({error:'agent_upgrade_required',requiredVersion:JOB_LEASE_PROTOCOL_VERSION});}const claimed=await claimNextAgentJob(db,{machineId,agentVersion:machine.agentVersion,now:new Date(),reclaimAfterSeconds:config.JOB_RECLAIM_AFTER_SECONDS});return claimed??reply.code(204).send();});

// Legacy GET control is kept only for a job that was already in flight before the
// nullable lease migration. New claims always have currentAttemptId/token and must
// use the body-signed POST route below.
app.get('/agent/jobs/:id/control',{config:{rateLimit:{max:120,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const machineId=String(req.headers['x-agent-machine-id']||'');const routePath=`/agent/jobs/${id}/control`;if(!machineId||!await authenticatedAgent(machineId,'GET',routePath,req.headers))return reply.code(401).send({error:'invalid_agent_request'});const job=await db.job.findFirst({where:{id,machineId},select:{status:true,cancelRequestedAt:true,currentAttemptId:true,leaseTokenHash:true}});if(!job)return reply.code(404).send({error:'job_not_found'});if(job.currentAttemptId!==null||job.leaseTokenHash!==null)return reply.code(426).send({error:'agent_upgrade_required',requiredVersion:JOB_LEASE_PROTOCOL_VERSION});return {cancelRequested:job.status===JobStatus.CANCEL_REQUESTED||job.cancelRequestedAt!==null};});

const requiredJobLeaseBody=z.object({machineId:z.string().cuid(),attemptId:z.string().cuid(),leaseToken:z.string().regex(JOB_LEASE_TOKEN_RE)});
app.post('/agent/jobs/:id/lease',{config:{rateLimit:{max:120,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=requiredJobLeaseBody.parse(req.body);const routePath=`/agent/jobs/${id}/lease`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const now=new Date();const updated=await db.job.updateMany({where:jobLeaseWhere({jobId:id,machineId:body.machineId,credentials:body,now}),data:{leaseExpiresAt:jobLeaseExpiresAt(now,config.JOB_RECLAIM_AFTER_SECONDS),lastAgentReportAt:now,updatedAt:now}});if(updated.count!==1)return reply.code(409).send({error:'stale_job_attempt'});return {ok:true,jobId:id,attemptId:body.attemptId,leaseExpiresAt:jobLeaseExpiresAt(now,config.JOB_RECLAIM_AFTER_SECONDS)};});

app.post('/agent/jobs/:id/control',{config:{rateLimit:{max:120,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=requiredJobLeaseBody.parse(req.body);const routePath=`/agent/jobs/${id}/control`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const now=new Date();const updated=await db.job.updateMany({where:jobLeaseWhere({jobId:id,machineId:body.machineId,credentials:body,now}),data:{leaseExpiresAt:jobLeaseExpiresAt(now,config.JOB_RECLAIM_AFTER_SECONDS),lastAgentReportAt:now,updatedAt:now}});if(updated.count!==1)return reply.code(409).send({error:'stale_job_attempt'});const job=await db.job.findFirst({where:{id,machineId:body.machineId,currentAttemptId:body.attemptId},select:{status:true,cancelRequestedAt:true}});if(!job)return reply.code(409).send({error:'stale_job_attempt'});return {cancelRequested:job.status===JobStatus.CANCEL_REQUESTED||job.cancelRequestedAt!==null};});

const jobProgress=z.enum(['DOWNLOADING','PREPARING','RUNNING','UPLOADING_RESULTS','CANCELLED','FAILED','TIMED_OUT','REJECTED','QUARANTINED']);
const workspacePreparationStep=z.enum(['WAITING_FOR_IMAGE_PULL','CHECKING_IMAGE_CACHE','PULLING_IMAGE','VERIFYING_IMAGE_DIGEST','IMAGE_CACHE_READY','VERIFYING_WORKSPACE','WORKSPACE_VERIFIED']);
const workspacePreparationProgress:Record<z.infer<typeof workspacePreparationStep>,number>={WAITING_FOR_IMAGE_PULL:30,CHECKING_IMAGE_CACHE:35,PULLING_IMAGE:40,VERIFYING_IMAGE_DIGEST:50,IMAGE_CACHE_READY:55,VERIFYING_WORKSPACE:55,WORKSPACE_VERIFIED:55};
const CLEANUP_UNVERIFIED_ERROR_CODES=new Set(['diagnostic_cleanup_unverified','gpu_proof_cleanup_unverified']);

app.post('/agent/jobs/:id/state',{config:{rateLimit:{max:120,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=z.object({machineId:z.string().cuid(),...jobLeaseFields,status:jobProgress,errorCode:z.string().max(100).optional()}).parse(req.body);if(!completeLeasePair(body))return reply.code(400).send({error:'incomplete_job_lease_credentials'});const routePath=`/agent/jobs/${id}/state`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const now=new Date();const next=body.status as JobStatus;const outcome=await db.$transaction(async tx=>{const job=await tx.job.findFirst({where:{id,machineId:body.machineId},select:{status:true,type:true,bookingId:true,currentAttemptId:true,leaseTokenHash:true}});if(!job)return {kind:'not_found'} as const;if(terminalJobStatusSet.has(job.status)){if(!terminalExecutionMatches(job,body))return {kind:'stale'} as const;if(job.status===next)return {kind:'ok',value:{id,status:job.status,duplicate:true}} as const;return {kind:'invalid',from:job.status,to:next} as const;}if(job.status===next){const refreshed=await tx.job.updateMany({where:{...executionWhere(id,body.machineId,body,now),status:job.status},data:executionRefresh(body,now)});return refreshed.count===1?{kind:'ok',value:{id,status:job.status,duplicate:true}} as const:{kind:'stale'} as const;}if(!canTransitionJob(job.status,next))return {kind:'invalid',from:job.status,to:next} as const;const terminal=terminalJobStatusSet.has(next);const cleanupUnverified=terminal&&!!body.errorCode&&CLEANUP_UNVERIFIED_ERROR_CODES.has(body.errorCode);const updated=await tx.job.updateMany({where:{...executionWhere(id,body.machineId,body,now),status:job.status},data:{status:next,...(body.errorCode?{errorCode:body.errorCode}:{}),...(next===JobStatus.RUNNING?{startedAt:now}:{}),...(terminal?{finishedAt:now,leaseExpiresAt:null,lastAgentReportAt:now}:{...executionRefresh(body,now)})}});if(updated.count!==1)return {kind:'stale'} as const;if(terminal){await tx.jobAttempt.updateMany({where:body.attemptId?{id:body.attemptId,jobId:id,finishedAt:null}:{jobId:id,finishedAt:null},data:{finishedAt:now,failureReason:body.errorCode||next}});const sessionStatus=next===JobStatus.CANCELLED?WorkspaceSessionStatus.CANCELLED:next===JobStatus.TIMED_OUT?WorkspaceSessionStatus.TIMED_OUT:next===JobStatus.QUARANTINED?WorkspaceSessionStatus.QUARANTINED:WorkspaceSessionStatus.FAILED;const reason=next===JobStatus.TIMED_OUT?SessionTerminationReason.TIMEOUT:next===JobStatus.QUARANTINED?SessionTerminationReason.SECURITY_POLICY:SessionTerminationReason.EXECUTION_FAILED;await tx.workspaceSession.updateMany({where:{jobId:id,status:WorkspaceSessionStatus.PREPARING},data:{status:sessionStatus,endedAt:now,terminationReason:reason,preparationStep:(body.errorCode||next).slice(0,80)}});}else if(job.type===JobType.WORKSPACE_PREPARE){const progress=next===JobStatus.DOWNLOADING?30:next===JobStatus.PREPARING?60:next===JobStatus.RUNNING?85:90;await tx.workspaceSession.updateMany({where:{jobId:id,status:WorkspaceSessionStatus.PREPARING},data:{preparationProgress:progress,preparationStep:next,...(next===JobStatus.DOWNLOADING?{preparationStartedAt:now}:{})}});}if(cleanupUnverified){await tx.booking.updateMany({where:{id:job.bookingId,status:{in:[BookingStatus.FUNDED,BookingStatus.STARTING,BookingStatus.ACTIVE]}},data:{status:BookingStatus.DEGRADED}});await tx.payment.updateMany({where:{bookingId:job.bookingId,status:PaymentStatus.ESCROW_FUNDED},data:{status:PaymentStatus.SETTLEMENT_PENDING}});await tx.machine.updateMany({where:{id:body.machineId,moderationStatus:ModerationStatus.CLEAR},data:{moderationStatus:ModerationStatus.QUARANTINED,operational:MachineOperational.UNAVAILABLE}});}return {kind:'ok',value:{id,status:next}} as const;},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});if(outcome.kind==='not_found')return reply.code(404).send({error:'job_not_found'});if(outcome.kind==='stale')return reply.code(409).send({error:'stale_job_attempt'});if(outcome.kind==='invalid')return reply.code(409).send({error:'invalid_job_transition',from:outcome.from,to:outcome.to});return outcome.value;});

app.post('/agent/jobs/:id/progress',{config:{rateLimit:{max:120,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=z.object({machineId:z.string().cuid(),...jobLeaseFields,step:workspacePreparationStep,elapsedSeconds:z.number().int().min(0).max(3600)}).parse(req.body);if(!completeLeasePair(body))return reply.code(400).send({error:'incomplete_job_lease_credentials'});const routePath=`/agent/jobs/${id}/progress`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const now=new Date();const result=await db.$transaction(async tx=>{const updated=await tx.job.updateMany({where:{...executionWhere(id,body.machineId,body,now),type:JobType.WORKSPACE_PREPARE,status:{in:[JobStatus.DOWNLOADING,JobStatus.PREPARING]}},data:executionRefresh(body,now)});if(updated.count!==1)return null;await tx.workspaceSession.updateMany({where:{jobId:id,status:WorkspaceSessionStatus.PREPARING},data:{preparationProgress:workspacePreparationProgress[body.step],preparationStep:body.step}});return {id,attemptId:body.attemptId??null,step:body.step,elapsedSeconds:body.elapsedSeconds,updatedAt:now};},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});return result??reply.code(409).send({error:'stale_job_attempt'});});

app.post('/agent/jobs/:id/logs',{config:{rateLimit:{max:120,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=z.object({machineId:z.string().cuid(),...jobLeaseFields,entries:z.array(z.object({level:z.enum(['DEBUG','INFO','WARN','ERROR']),message:z.string().trim().min(1).max(2000)})).min(1).max(50)}).parse(req.body);if(!completeLeasePair(body))return reply.code(400).send({error:'incomplete_job_lease_credentials'});const routePath=`/agent/jobs/${id}/logs`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const now=new Date();const accepted=await db.$transaction(async tx=>{const lease=await tx.job.updateMany({where:executionWhere(id,body.machineId,body,now),data:executionRefresh(body,now)});if(lease.count!==1)return null;const count=await tx.jobLog.count({where:{jobId:id}});if(count+body.entries.length>10_000)return -1;await tx.jobLog.createMany({data:body.entries.map(entry=>({jobId:id,...entry}))});return body.entries.length;},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});if(accepted===null)return reply.code(409).send({error:'stale_job_attempt'});if(accepted<0)return reply.code(413).send({error:'job_log_limit_reached'});return {ok:true,accepted};});

app.post('/agent/jobs/:id/complete',{config:{rateLimit:{max:30,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=z.object({machineId:z.string().cuid(),...jobLeaseFields,result:z.object({gpuDetected:z.boolean(),summary:z.string().max(1000),metrics:z.record(z.string(),z.union([z.string(),z.number(),z.boolean(),z.null()])).optional()}).strict()}).parse(req.body);if(!completeLeasePair(body))return reply.code(400).send({error:'incomplete_job_lease_credentials'});const routePath=`/agent/jobs/${id}/complete`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const now=new Date();const outcome=await db.$transaction(async tx=>{const job=await tx.job.findFirst({where:{id,machineId:body.machineId},select:{status:true,type:true,currentAttemptId:true,leaseTokenHash:true}});if(!job)return {kind:'not_found'} as const;if(terminalJobStatusSet.has(job.status)){if(!terminalExecutionMatches(job,body))return {kind:'stale'} as const;if(job.status===JobStatus.COMPLETED)return {kind:'ok',value:{id,status:JobStatus.COMPLETED,workspaceReady:job.type===JobType.WORKSPACE_PREPARE,duplicate:true}} as const;return {kind:'invalid',from:job.status,to:JobStatus.COMPLETED} as const;}if(!canTransitionJob(job.status,JobStatus.COMPLETED))return {kind:'invalid',from:job.status,to:JobStatus.COMPLETED} as const;const isPreparation=job.type===JobType.WORKSPACE_PREPARE;if(isPreparation){const session=await tx.workspaceSession.findFirst({where:{jobId:id},select:{status:true}});if(!session||session.status!==WorkspaceSessionStatus.PREPARING)return {kind:'session_inactive'} as const;}const updated=await tx.job.updateMany({where:{...executionWhere(id,body.machineId,body,now),status:job.status},data:{status:JobStatus.COMPLETED,result:body.result,finishedAt:now,leaseExpiresAt:null,lastAgentReportAt:now}});if(updated.count!==1)return {kind:'stale'} as const;await tx.jobAttempt.updateMany({where:body.attemptId?{id:body.attemptId,jobId:id,finishedAt:null}:{jobId:id,finishedAt:null},data:{finishedAt:now,exitCode:0}});if(isPreparation)await tx.workspaceSession.updateMany({where:{jobId:id,status:WorkspaceSessionStatus.PREPARING},data:{status:WorkspaceSessionStatus.READY,readyAt:now,preparationProgress:100,preparationStep:'CONNECTION_READY',preparationCompletedAt:now}});else await tx.workspaceSession.updateMany({where:{jobId:id,status:{in:[WorkspaceSessionStatus.RESERVED,WorkspaceSessionStatus.PREPARING,WorkspaceSessionStatus.READY,WorkspaceSessionStatus.RUNNING]}},data:{status:WorkspaceSessionStatus.COMPLETED,endedAt:now,terminationReason:SessionTerminationReason.COMPLETED}});return {kind:'ok',value:{id,status:JobStatus.COMPLETED,workspaceReady:isPreparation}} as const;},{isolationLevel:Prisma.TransactionIsolationLevel.Serializable});if(outcome.kind==='not_found')return reply.code(404).send({error:'job_not_found'});if(outcome.kind==='stale')return reply.code(409).send({error:'stale_job_attempt'});if(outcome.kind==='session_inactive')return reply.code(409).send({error:'workspace_session_not_preparing'});if(outcome.kind==='invalid')return reply.code(409).send({error:'invalid_job_transition',from:outcome.from,to:outcome.to});return outcome.value;});

app.post('/agent/jobs/:id/finalize-proof',{config:{rateLimit:{max:30,timeWindow:'1 minute'}}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=z.object({machineId:z.string().cuid(),...jobLeaseFields}).parse(req.body);if(!completeLeasePair(body))return reply.code(400).send({error:'incomplete_job_lease_credentials'});const routePath=`/agent/jobs/${id}/finalize-proof`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const job=await db.job.findFirst({where:{id,machineId:body.machineId,type:JobType.GPU_PROOF,status:JobStatus.COMPLETED},include:{booking:true,workspaceSession:{include:{metrics:{where:{workloadProof:true},select:{intervalSeconds:true}}}}}});if(!job||!job.workspaceSession)return reply.code(409).send({error:'completed_gpu_proof_required'});if(!terminalExecutionMatches(job,body))return reply.code(409).send({error:'stale_job_attempt'});const result=job.result as {gpuDetected?:unknown;metrics?:{containerCleaned?:unknown}}|null;if(result?.gpuDetected!==true||result.metrics?.containerCleaned!==true)return reply.code(409).send({error:'verified_gpu_proof_required'});const provenSeconds=job.workspaceSession.metrics.reduce((total,metric)=>total+metric.intervalSeconds,0);if(provenSeconds<1||job.booking.validSeconds<1)return reply.code(409).send({error:'signed_usage_proof_required'});
  const outcome=await completeGpuProofJob(db,job.bookingId,body.machineId);
  return {ok:true,...outcome,provenSeconds};
});
app.get('/listings',async()=>{const now=new Date();const rows=await db.gpuListing.findMany({where:{status:ListingStatus.ACTIVE,machine:{connectivity:MachineConnectivity.ONLINE,moderationStatus:ModerationStatus.CLEAR,lastCudaProbeOk:true,lastHeartbeatAt:{gte:new Date(Date.now()-config.HEARTBEAT_OFFLINE_SECONDS*1000)}}},select:{id:true,title:true,description:true,hourlyLamports:true,createdAt:true,machine:{select:{gpuModel:true,vramMiB:true,verifiedAt:true}},owner:{select:{pseudonym:true,profile:{select:{reliabilityScore:true,completedSessions:true}}}},bookings:{where:{status:{in:[BookingStatus.AWAITING_DEPOSIT,BookingStatus.FUNDED,BookingStatus.STARTING,BookingStatus.ACTIVE]},endsAt:{gt:now}},select:{status:true,endsAt:true},orderBy:{endsAt:'desc'},take:1}},take:100,orderBy:{createdAt:'desc'}});return rows.map(({bookings,...r})=>{const active=bookings[0];const availability=!active?{state:'AVAILABLE',label:'Disponible',availableAt:null}:active.status===BookingStatus.ACTIVE?{state:'WORKING',label:'En travail',availableAt:active.endsAt}:{state:'RENTED',label:'En location',availableAt:active.endsAt};return {...r,hourlyLamports:bigintJson(r.hourlyLamports),availability}})});
app.get('/listings/:listingId/workspaces',async(req,reply)=>{const {listingId}=z.object({listingId:z.string().cuid()}).parse(req.params);const listing=await db.gpuListing.findFirst({where:{id:listingId,status:ListingStatus.ACTIVE,machine:{connectivity:MachineConnectivity.ONLINE,moderationStatus:ModerationStatus.CLEAR,lastCudaProbeOk:true,lastHeartbeatAt:{gte:new Date(Date.now()-config.HEARTBEAT_OFFLINE_SECONDS*1000)}}},select:{id:true,title:true,hourlyLamports:true,machine:{select:{gpuModel:true,vramMiB:true,ramTotalMiB:true,diskTotalMiB:true,cudaVersion:true,dockerAvailable:true,nvidiaRuntimeAvailable:true,operatingSystem:true,virtualizationAvailable:true}}}});if(!listing)return reply.code(404).send({error:'listing_unavailable'});return {...listing,hourlyLamports:bigintJson(listing.hourlyLamports),workspaces:compatibleWorkspaceChoices(listing.machine)};});
app.post('/bookings',async(req,reply)=>{const s=await requireSession(req,reply,redis);if(!s)return;const b=z.object({listingId:z.string().cuid(),startsAt:z.string().datetime(),endsAt:z.string().datetime(),idempotencyKey:z.string().uuid(),acceleratorIds:z.array(z.string().cuid()).max(64).optional()}).parse(req.body);const start=new Date(b.startsAt),end=new Date(b.endsAt);if(start.getTime()<Date.now()-60_000||start.getTime()>Date.now()+30*24*3600_000||end<=start||end.getTime()-start.getTime()>24*3600_000)return reply.code(400).send({error:'invalid_period'});const booking=await runBookingTransaction(db,async tx=>{const existing=await tx.booking.findUnique({where:{buyerId_idempotencyKey:{buyerId:s.userId,idempotencyKey:b.idempotencyKey}}});if(existing)return existing;const listing=await tx.gpuListing.findFirst({where:{id:b.listingId,status:ListingStatus.ACTIVE,machine:{connectivity:MachineConnectivity.ONLINE,lastCudaProbeOk:true}},select:{id:true,hourlyLamports:true,ownerId:true}});if(!listing||listing.ownerId===s.userId)throw new Error('listing_unavailable');const overlap=await tx.booking.count({where:{listingId:listing.id,status:{in:[BookingStatus.AWAITING_DEPOSIT,BookingStatus.FUNDED,BookingStatus.STARTING,BookingStatus.ACTIVE]},startsAt:{lt:end},endsAt:{gt:start}}});if(overlap)throw new Error('time_slot_unavailable');const expected=Math.ceil((end.getTime()-start.getTime())/1000);const quote=listing.hourlyLamports*BigInt(expected)/3600n;if(quote<=0n)throw new Error('quote_too_small');return tx.booking.create({data:{buyerId:s.userId,listingId:listing.id,startsAt:start,endsAt:end,quotedLamports:quote,expectedSeconds:expected,idempotencyKey:b.idempotencyKey,status:BookingStatus.AWAITING_DEPOSIT}})}).catch(e=>{const msg=e instanceof Error?e.message:'booking_failed';if(!BOOKING_BUSINESS_ERRORS.has(msg)){req.log.error({err:e},'booking_transaction_failed');throw e;}return reply.code(409).send({error:msg})});if(!('id'in booking))return booking;try{await allocateBookingResources(db,{bookingId:booking.id,buyerId:s.userId,...(b.acceleratorIds?{acceleratorIds:b.acceleratorIds}:{})})}catch(error){if(!(error instanceof ResourceAllocationError&&error.code==='allocation_already_exists')){await db.booking.delete({where:{id:booking.id}}).catch(()=>{});const code=error instanceof ResourceAllocationError?error.code:'resource_allocation_failed';req.log.warn({bookingId:booking.id,listingId:b.listingId,acceleratorIds:b.acceleratorIds,code},'rental_resource_allocation_failed');return reply.code(409).send({error:code})}}return {...booking,quotedLamports:bigintJson(booking.quotedLamports)}});

app.post('/bookings/:id/payment-intent',async(req,reply)=>{const s=await requireSession(req,reply,redis);if(!s)return; if(config.ESCROW_PROGRAM_ID==='NOT_DEPLOYED_YET')return reply.code(503).send({error:'escrow_not_deployed'}); const {id}=z.object({id:z.string().cuid()}).parse(req.params); const b=await db.booking.findFirst({where:{id,buyerId:s.userId,status:BookingStatus.AWAITING_DEPOSIT},include:{buyer:true,listing:{include:{owner:true}}}}); if(!b)return reply.code(404).send({error:'booking_not_found'}); const programId=new PublicKey(config.ESCROW_PROGRAM_ID); const buyer=new PublicKey(b.buyer.wallet); const provider=new PublicKey(b.listing.owner.wallet); const expiresAtUnix=bookingEscrowExpiryUnix(b.endsAt); const built=await buildOpenEscrowTransaction({rpcUrl:config.SOLANA_RPC_URL,commitment:config.SOLANA_COMMITMENT,programId,buyer,provider,bookingId:b.id,amount:b.quotedLamports,expectedSeconds:b.expectedSeconds,expiresAtUnix}); await db.booking.update({where:{id:b.id},data:{escrowAddress:built.escrow.toBase58()}}); return {transactionBase64:built.transactionBase64,escrowAddress:built.escrow.toBase58(),programId:programId.toBase58(),amountLamports:b.quotedLamports.toString(),cluster:config.SOLANA_CLUSTER};});
app.post('/bookings/:id/confirm-deposit',async(req,reply)=>{const s=await requireSession(req,reply,redis);if(!s)return; if(config.ESCROW_PROGRAM_ID==='NOT_DEPLOYED_YET')return reply.code(503).send({error:'escrow_not_deployed'}); const {id}=z.object({id:z.string().cuid()}).parse(req.params); const {signature}=z.object({signature:z.string().min(64).max(100)}).parse(req.body); const b=await db.booking.findFirst({where:{id,buyerId:s.userId},include:{buyer:true,listing:{include:{owner:true}}}}); if(!b)return reply.code(404).send({error:'booking_not_found'}); if(b.depositSignature&&b.depositSignature!==signature)return reply.code(409).send({error:'deposit_already_recorded'}); const programId=new PublicKey(config.ESCROW_PROGRAM_ID); const {escrow}=deriveEscrowAddresses(programId,b.id); const ok=await verifyOpenEscrowTransaction({rpcUrl:config.SOLANA_RPC_URL,commitment:config.SOLANA_COMMITMENT,programId,signature,buyer:new PublicKey(b.buyer.wallet),provider:new PublicKey(b.listing.owner.wallet),amount:b.quotedLamports,expectedSeconds:b.expectedSeconds,escrow}); if(!ok)return reply.code(409).send({error:'invalid_deposit_transaction'}); await db.$transaction([db.booking.update({where:{id:b.id},data:{status:BookingStatus.FUNDED,escrowAddress:escrow.toBase58(),depositSignature:signature}}),db.payment.upsert({where:{bookingId:b.id},update:{grossLamports:b.quotedLamports,status:PaymentStatus.ESCROW_FUNDED},create:{bookingId:b.id,grossLamports:b.quotedLamports,status:PaymentStatus.ESCROW_FUNDED}})]); let workspaceSession=null;try{workspaceSession=await ensureComputePreparation(b.id,s.userId)}catch(error){req.log.error({err:error,bookingId:b.id},'workspace_preparation_enqueue_failed')}return {ok:true,status:'FUNDED',signature,escrowAddress:escrow.toBase58(),workspaceSession};});
// AWAITING_DEPOSIT is the only status where cancelling is free of consequence - no escrow
// deposit or workspace runtime exists yet, so this can never orphan a container or leave
// money in limbo. Renters had no way to release an abandoned/never-funded booking, which
// left it counted against overlap checks (time_slot_unavailable) on that listing forever.
app.post('/bookings/:id/cancel',async(req,reply)=>{const s=await requireSession(req,reply,redis);if(!s)return;const {id}=z.object({id:z.string().cuid()}).parse(req.params);const updated=await db.booking.updateMany({where:{id,buyerId:s.userId,status:BookingStatus.AWAITING_DEPOSIT},data:{status:BookingStatus.CANCELLED}});if(updated.count!==1)return reply.code(409).send({error:'cancel_not_allowed'});return {ok:true,status:'CANCELLED'};});

app.get('/bookings/:id/settlement-preview',async(req,reply)=>{const s=await requireSession(req,reply,redis);if(!s)return;const {id}=z.object({id:z.string().cuid()}).parse(req.params);const b=await db.booking.findFirst({where:{id,OR:[{buyerId:s.userId},{listing:{ownerId:s.userId}}]},include:{payment:true}});if(!b||!b.payment)return reply.code(404).send({error:'not_found'});const x=calculateSettlement(b.payment.grossLamports,b.validSeconds,b.expectedSeconds,config.COMMISSION_BPS);return Object.fromEntries(Object.entries(x).map(([k,v])=>[k,typeof v==='bigint'?v.toString():v]))});
app.post('/internal/sweep-offline',{config:{rateLimit:{max:30,timeWindow:'1 minute'}}},async(req,reply)=>{if(!constantTimeToken(req.headers.authorization?.replace(/^Bearer\s+/i,''),config.INTERNAL_SERVICE_TOKEN))return reply.code(401).send({error:'unauthorized'});const offline=await sweepOfflineMachines(db,new Date(),config.HEARTBEAT_OFFLINE_SECONDS);const staleJobs=await sweepStaleJobs(db,new Date(),config.JOB_STALE_AFTER_SECONDS);req.log.info({offline:{...offline,cutoff:offline.cutoff.toISOString()},staleJobs:{...staleJobs,cutoff:staleJobs.cutoff.toISOString()}},'offline_sweep_completed');return {offline:{...offline,cutoff:offline.cutoff.toISOString()},staleJobs:{...staleJobs,cutoff:staleJobs.cutoff.toISOString()}}});
const settlementJson=(s:{[k:string]:unknown})=>Object.fromEntries(Object.entries(s).map(([k,v])=>[k,typeof v==='bigint'?v.toString():v]));
app.post('/internal/bookings/:id/settlement/request',{config:{rateLimit:{max:30,timeWindow:'1 minute'}}},async(req,reply)=>{if(!constantTimeToken(req.headers.authorization?.replace(/^Bearer\s+/i,''),config.INTERNAL_SERVICE_TOKEN))return reply.code(401).send({error:'unauthorized'});const {id}=z.object({id:z.string().cuid()}).parse(req.params);try{const result=await requestSettlement(db,id);return {...result,settlement:settlementJson(result.settlement)}}catch(e){req.log.warn({err:e,bookingId:id},'settlement_request_failed');return reply.code(409).send({error:e instanceof Error?e.message:'settlement_request_failed'})}});
app.post('/internal/bookings/:id/settlement/confirm',{config:{rateLimit:{max:30,timeWindow:'1 minute'}}},async(req,reply)=>{if(!constantTimeToken(req.headers.authorization?.replace(/^Bearer\s+/i,''),config.INTERNAL_SERVICE_TOKEN))return reply.code(401).send({error:'unauthorized'});const {id}=z.object({id:z.string().cuid()}).parse(req.params);const {signature}=z.object({signature:z.string().min(32).max(128)}).parse(req.body);try{const result=await confirmSettlement(db,id,signature);return {...result,settlement:settlementJson(result.settlement)}}catch(e){req.log.warn({err:e,bookingId:id},'settlement_confirm_failed');return reply.code(409).send({error:e instanceof Error?e.message:'settlement_confirm_failed'})}});
app.post('/internal/bookings/:id/payment/unfreeze',{config:{rateLimit:{max:30,timeWindow:'1 minute'}}},async(req,reply)=>{if(!constantTimeToken(req.headers.authorization?.replace(/^Bearer\s+/i,''),config.INTERNAL_SERVICE_TOKEN))return reply.code(401).send({error:'unauthorized'});const {id}=z.object({id:z.string().cuid()}).parse(req.params);const updated=await db.payment.updateMany({where:{bookingId:id,status:PaymentStatus.FROZEN},data:{status:PaymentStatus.ESCROW_FUNDED}});if(updated.count!==1)return reply.code(409).send({error:'payment_not_frozen'});req.log.warn({bookingId:id},'payment_manually_unfrozen');return {ok:true,bookingId:id,status:PaymentStatus.ESCROW_FUNDED};});
const storageDir=path.resolve(config.FILE_STORAGE_DIR);fs.mkdirSync(storageDir,{recursive:true});
app.post('/jobs/:id/artifacts',{config:{rateLimit:{max:20,timeWindow:'1 minute'},bodyLimit:config.MAX_ARTIFACT_BYTES}},async(req,reply)=>{const {id}=z.object({id:z.string().cuid()}).parse(req.params);const body=z.object({machineId:z.string().cuid(),kind:z.string().max(32).default('result'),sha256:z.string().regex(/^[a-f0-9]{64}$/),sizeBytes:z.number().int().min(1).max(config.MAX_ARTIFACT_BYTES)}).parse(req.query);const routePath=`/jobs/${id}/artifacts`;if(!await authenticatedAgentWithBody(body.machineId,'POST',routePath,req.headers,req.rawBody))return reply.code(401).send({error:'invalid_agent_request'});const job=await db.job.findFirst({where:{id,machineId:body.machineId},select:{id:true,renterId:true}});if(!job)return reply.code(404).send({error:'job_not_found'});const data=await req.body;if(!Buffer.isBuffer(data)&&typeof data!=='string')return reply.code(400).send({error:'binary_body_required'});const buf=Buffer.from(data);if(buf.length>config.MAX_ARTIFACT_BYTES)return reply.code(413).send({error:'artifact_too_large'});const hash=crypto.createHash('sha256').update(buf).digest('hex');if(hash!==body.sha256)return reply.code(400).send({error:'integrity_check_failed'});const storageKey=`${id}/${body.kind}/${body.sha256}`;const filePath=path.join(storageDir,storageKey);await fsp.mkdir(path.dirname(filePath),{recursive:true});await fsp.writeFile(filePath,buf);const artifact=await db.jobArtifact.create({data:{jobId:id,kind:body.kind,sha256:body.sha256,sizeBytes:buf.length,storageKey}});return reply.code(201).send({id:artifact.id,sha256:body.sha256,sizeBytes:buf.length,storageKey});});
app.get('/jobs/:id/artifacts',async(req,reply)=>{const session=await requireSession(req,reply,redis);if(!session)return;const {id}=z.object({id:z.string().cuid()}).parse(req.params);const job=await db.job.findFirst({where:{id,renterId:session.userId},select:{id:true}});if(!job)return reply.code(404).send({error:'job_not_found'});const artifacts=await db.jobArtifact.findMany({where:{jobId:id},select:{id:true,kind:true,sha256:true,sizeBytes:true,storageKey:true,createdAt:true},orderBy:{createdAt:'desc'}});return {artifacts};});
app.get('/jobs/:id/artifacts/:artifactId',async(req,reply)=>{const session=await requireSession(req,reply,redis);if(!session)return;const {id,artifactId}=z.object({id:z.string().cuid(),artifactId:z.string().cuid()}).parse(req.params);const job=await db.job.findFirst({where:{id,renterId:session.userId},select:{id:true}});if(!job)return reply.code(404).send({error:'job_not_found'});const artifact=await db.jobArtifact.findFirst({where:{id:artifactId,jobId:id},select:{id:true,sha256:true,sizeBytes:true,storageKey:true,kind:true}});if(!artifact)return reply.code(404).send({error:'artifact_not_found'});const filePath=path.join(storageDir,artifact.storageKey);try{const data=await fsp.readFile(filePath);reply.header('content-type','application/octet-stream');reply.header('x-artifact-sha256',artifact.sha256);return reply.send(data);}catch{return reply.code(404).send({error:'file_not_found_on_disk'});}});
await app.register(fastifyStatic,{root:path.resolve(process.cwd(),'../web'),prefix:'/'});
app.setNotFoundHandler((req,reply)=>{if(req.method==='GET'&&!req.url.startsWith('/api/')&&!req.url.startsWith('/internal/'))return reply.sendFile('index.html');return reply.code(404).send({error:'not_found'})});
// Render's free plan does not support the Background Worker service type (the delivery-worker
// and sweep-scheduler processes defined in render.yaml fail to deploy on it — confirmed via a
// failed blueprint sync: "service type is not available for this plan"). Until either a paid
// plan or the two dedicated workers are available, the two reconciliation loops they'd normally
// run run in-process here instead, on plain intervals (single process, so no distributed lock
// is needed the way the dedicated sweep-scheduler needs one across multiple replicas).
let reconciling=false;
const reconcileIntervalId=setInterval(()=>{if(reconciling)return;reconciling=true;const now=new Date();Promise.all([reconcileDevelopmentBookings(db,now).then(result=>{if(Object.values(result).some(v=>v>0))app.log.info({...result},'gpu_booking_reconciled');}).catch(err=>app.log.error({err},'gpu_booking_reconcile_failed')),reconcileStalledActivations(db,now).then(result=>{if(result.degraded>0)app.log.info({...result},'stalled_booking_activation_degraded');}).catch(err=>app.log.error({err},'stalled_activation_reconcile_failed')),reconcileOrphanedDepositBookings(db,now).then(result=>{if(result.cancelled>0)app.log.info({...result},'orphaned_deposit_bookings_cancelled');}).catch(err=>app.log.error({err},'orphaned_deposit_reconcile_failed')),reconcileDevBypassSettlements(db,now).then(result=>{if(result.settled>0)app.log.info({settled:result.settled},'dev_bypass_bookings_settled');if(result.failed.length>0)app.log.warn({failed:result.failed},'dev_bypass_settlement_attempt_failed');}).catch(err=>app.log.error({err},'dev_bypass_settlement_reconcile_failed'))]).finally(()=>{reconciling=false});},10_000);
let sweeping=false;
const sweepIntervalId=setInterval(()=>{if(sweeping)return;sweeping=true;(async()=>{const offline=await sweepOfflineMachines(db,new Date(),config.HEARTBEAT_OFFLINE_SECONDS);const staleJobs=await sweepStaleJobs(db,new Date(),config.JOB_STALE_AFTER_SECONDS);if(offline.machinesOffline>0||staleJobs.jobsTimedOut>0||staleJobs.jobsFailed>0)app.log.info({offline:{...offline,cutoff:offline.cutoff.toISOString()},staleJobs:{...staleJobs,cutoff:staleJobs.cutoff.toISOString()}},'offline_sweep_completed');})().catch(err=>app.log.error({err},'offline_sweep_failed')).finally(()=>{sweeping=false});},Math.max(config.HEARTBEAT_OFFLINE_SECONDS,30)*1000);
const shutdown=async(signal:string)=>{app.log.info({signal},'shutdown');clearInterval(reconcileIntervalId);clearInterval(sweepIntervalId);await app.close();await db.$disconnect();redis.disconnect();process.exit(0)};
process.once('SIGTERM',()=>void shutdown('SIGTERM'));process.once('SIGINT',()=>void shutdown('SIGINT'));
await app.listen({host:'0.0.0.0',port:config.PORT});
